import SwiftUI

struct MemoryDetailView: View { @StateObject var viewModel: MemoryDetailViewModel
    var body: some View { ScrollView { VStack(alignment:.leading, spacing:MindMorySpacing.lg){ MemoryImagePlaceholderView(imageName:viewModel.memory.imageName).frame(height:260).clipShape(RoundedRectangle(cornerRadius: MindMoryRadius.extraLarge)); HStack{ VStack(alignment:.leading){ Text(viewModel.memory.title).font(MindMoryTypography.headingLarge); Text(viewModel.memory.dateText).font(MindMoryTypography.bodySmall).foregroundStyle(MindMoryColors.textSecondary); if let location = viewModel.memory.locationName { Label(location, systemImage:"mappin.circle").font(MindMoryTypography.bodySmall).foregroundStyle(MindMoryColors.primaryGreen) } }; Spacer(); Button(action:viewModel.toggleFavorite){ Image(systemName: viewModel.memory.isFavorite ? "star.fill" : "star").font(.title2).foregroundStyle(MindMoryColors.primaryGreen) } }; Text(viewModel.memory.subtitle).font(MindMoryTypography.bodyLarge).foregroundStyle(MindMoryColors.textPrimary); JournalEntryView(text:$viewModel.journalText, saveAction:viewModel.saveJournal); PrimaryButton(title:"Share as Memory Frame", action:viewModel.prepareShareFrame); if let shareable = viewModel.shareableMemory { ShareableMemoryFrameView(shareableMemory: shareable) } }.padding(MindMorySpacing.xl) }.background(MindMoryColors.background.ignoresSafeArea()) }
}
